# Generated by build.py from recipe.yml for recipe surl-read-options-from-a-file. Do not edit.
set -e
cd "$(dirname "$0")"
mkdir -p site
printf '%s\n' 'hello from surl' > site/hello.txt
awk '{printf "%s\r\n", $0}' > mail.txt <<'EOF'
From: ann@example.com
To: carol@elsewhere.org
Subject: Hello

Hi.
EOF
cat > surl.cfg <<'EOF'
# Options for surl -K surl.cfg, one per line.
# The dashes are optional, and so is the = between name and value.
directory = site
user = alice:secret
mail-domain = example.com
--mailbox ann@example.com:secret
EOF
printf '%s\n' 'directory = missing' > no-url.cfg
cat > with-url.cfg <<'EOF'
url = http://127.0.0.1:0/
directory = missing
EOF
printf '%s\n' 'directroy = site' > typo.cfg
surl -K surl.cfg http://127.0.0.1:8080/ smtp://127.0.0.1:8081/ &
sleep 1
curl -s --digest -u alice:secret http://127.0.0.1:8080/hello.txt
kill $(jobs -p)
